// TypeScript Version: 4.1

/**
* Compute the squared hinge loss.
*
* ## Notes
*
* -   If `y` is not +1 or -1, the function returns `NaN`.
* -   When `t = 1.0`, we get the loss used by SVM.
*
* @param t - margin threshold
* @param y - true target value
* @param p - predicted value
* @returns squared hinge loss
*
* @example
* var v = squaredHinge( 1.0, 1.0, 0.782 );
* // returns ~0.0475
*
* @example
* var v = squaredHinge( 1.0, 1.0, 0.202 );
* // returns ~0.6368
*
* @example
* var v = squaredHinge( 1.0, 1.0, -0.999 );
* // returns ~3.996
*
* @example
* var v = squaredHinge( 1.0, -1.0, 0.2 );
* // returns 1.44
*
* @example
* var v = squaredHinge( 1.0, -1.0, -1.5 );
* // returns 0.0
*/
declare function squaredHinge( t: number, y: number, p: number ): number;


// EXPORTS //

export = squaredHinge;
